import{_ as r,C as o,o as t,c as s,a2 as i,b as l,w as a,a as d,E as c,a3 as m}from"./chunks/framework.RycU2wFZ.js";const x=JSON.parse('{"title":"O(1) Streaming & Memory Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/streaming-and-memory.md","filePath":"guide/streaming-and-memory.md","lastUpdated":null}'),h={name:"guide/streaming-and-memory.md"};function g(p,e,u,f,y,k){const n=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="o-1-streaming-memory-architecture" tabindex="-1">O(1) Streaming &amp; Memory Architecture <a class="header-anchor" href="#o-1-streaming-memory-architecture" aria-label="Permalink to &quot;O(1) Streaming &amp; Memory Architecture&quot;">​</a></h1><p>Most OpenStreetMap ingestion pipelines fail on planet-scale datasets because they attempt to load entity graphs or large geographic hierarchies into RAM. In contrast, <strong>Geomilli</strong> is built strictly around <strong>O(1) streaming and disk-first processing</strong>.</p><p>Whether processing a single region like Belgium (<code>BE</code>, ~70 MB PBF) or the entire Planet (~75 GB PBF), the Go ingestion daemon operates under a <strong>deterministic heap footprint of less than 50 MB RAM</strong>.</p><hr><h2 id="the-four-pillars-of-low-memory-ingestion" tabindex="-1">The Four Pillars of Low-Memory Ingestion <a class="header-anchor" href="#the-four-pillars-of-low-memory-ingestion" aria-label="Permalink to &quot;The Four Pillars of Low-Memory Ingestion&quot;">​</a></h2>',5)),(t(),l(m,null,{default:a(()=>[c(n,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20P1%5B%221.%20Pipeline%20Stream%20Transformation%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22Disk%20.osm.pbf%22%5D%20--%3E%7C%22osmium%20tags-filter%22%7C%20B%5B%22Disk%20filtered.osm.pbf%22%5D%0A%20%20%20%20%20%20%20%20B%20--%3E%7C%22osmium%20export%20(GeoJSONSeq)%22%7C%20C%5B%22Line-Delimited%20Features%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%7C%22bufio.Scanner%20(64KB)%22%7C%20D%5B%22NDJSON%20Staging%20File%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P2%5B%222.%20Bounded%20Worker%20Enrichment%22%5D%0A%20%20%20%20%20%20%20%20D%20--%3E%7C%22Batch%20Channel%20(cap%3Dworkers*2)%22%7C%20E%5B%22Wikidata%20Worker%20Pool%22%5D%0A%20%20%20%20%20%20%20%20E%20--%3E%7C%22Zero-Allocation%20Channel%22%7C%20F%5B%22Enriched%20NDJSON%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P3%5B%223.%20Bounded-Pool%20Indexing%22%5D%0A%20%20%20%20%20%20%20%20F%20--%3E%7C%22StreamJSONLGlob%20(max%202%20files)%22%7C%20G%5B%22Meilisearch%20NDJSON%20Batches%22%5D%0A%20%20%20%20%20%20%20%20G%20--%3E%7C%22maxInFlight%3D2%20(1%2C000%20docs)%22%7C%20H%5B%22Shadow%20Index%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P4%5B%224.%20Immediate%20Cleanup%22%5D%0A%20%20%20%20%20%20%20%20F%20-.-%3E%7C%22Unlink%20raw%20PBF%20%26%20geojsonseq%22%7C%20Clean%5B%22Reclaimed%20Disk%20Space%22%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i(`<hr><h2 id="_1-zero-allocation-enrichment-pipeline" tabindex="-1">1. Zero-Allocation Enrichment Pipeline <a class="header-anchor" href="#_1-zero-allocation-enrichment-pipeline" aria-label="Permalink to &quot;1. Zero-Allocation Enrichment Pipeline&quot;">​</a></h2><h3 id="the-problem-in-traditional-pipelines" tabindex="-1">The Problem in Traditional Pipelines <a class="header-anchor" href="#the-problem-in-traditional-pipelines" aria-label="Permalink to &quot;The Problem in Traditional Pipelines&quot;">​</a></h3><p>Common ingestion architectures maintain an in-memory buffer or map (e.g. <code>map[int]Place</code>) to preserve entity sequence order across parallel workers. If a single external HTTP call (such as a Wikidata or Wikipedia query) stalls or hits rate limits, thousands of pending records accumulate in heap memory, triggering an Out-Of-Memory (OOM) crash.</p><h3 id="geomilli-s-bounded-channel-pattern" tabindex="-1">Geomilli&#39;s Bounded Channel Pattern <a class="header-anchor" href="#geomilli-s-bounded-channel-pattern" aria-label="Permalink to &quot;Geomilli&#39;s Bounded Channel Pattern&quot;">​</a></h3><p>Because Meilisearch does not rely on document insertion order, <code>geomilli-harvester</code> eliminates accumulator maps entirely:</p><ul><li>Workers read from a <strong>bounded batch channel</strong> (<code>cap = workers * 2</code>).</li><li>Workers stream enriched records directly to disk via an atomic mutex-protected or dedicated writer goroutine.</li><li>Memory consumption remains strictly bounded regardless of worker throughput or external API latency.</li></ul><hr><h2 id="_2-bounded-file-streaming-in-the-indexer" tabindex="-1">2. Bounded File Streaming in the Indexer <a class="header-anchor" href="#_2-bounded-file-streaming-in-the-indexer" aria-label="Permalink to &quot;2. Bounded File Streaming in the Indexer&quot;">​</a></h2><p>When indexing 200+ countries, naive implementations often launch a goroutine and a large <code>16 MB</code> scanner buffer for every matched <code>.ndjson</code> file simultaneously, demanding several gigabytes of RAM.</p><p>In <code>geomilli-harvester</code>:</p><ul><li>The indexer processes countries using a <strong>bounded worker pool</strong> (default: 2 concurrent files).</li><li>Each file scanner uses a reusable <strong><code>256 KB</code> buffer</strong>.</li><li>Documents are batched into chunks of <strong>1,000–2,500 records</strong> (<code>maxInFlight = 2</code>), applying backpressure to disk reading until Meilisearch acknowledges task ingestion.</li></ul><hr><h2 id="_3-immediate-per-country-disk-reclaim" tabindex="-1">3. Immediate Per-Country Disk Reclaim <a class="header-anchor" href="#_3-immediate-per-country-disk-reclaim" aria-label="Permalink to &quot;3. Immediate Per-Country Disk Reclaim&quot;">​</a></h2><p>Disk space is treated as a finite resource:</p><ol><li><code>raw/*.osm.pbf</code> and intermediate <code>.geojsonseq</code> files for country $N$ are unlinked immediately after producing <code>staging/places_osm_{code}.ndjson</code>.</li><li>Peak disk usage during a multi-country or planet run is proportional to the active country rather than the cumulative sum of all countries.</li></ol><hr><h2 id="_4-meilisearch-indexing-memory-tuning" tabindex="-1">4. Meilisearch Indexing Memory Tuning <a class="header-anchor" href="#_4-meilisearch-indexing-memory-tuning" aria-label="Permalink to &quot;4. Meilisearch Indexing Memory Tuning&quot;">​</a></h2><p>Meilisearch utilizes LMDB (Lightning Memory-Mapped Database), which is inherently disk-backed. In Docker Compose and Kubernetes configurations, we tune indexing memory to prevent Meilisearch from consuming all host RAM:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MEILI_MAX_INDEXING_MEMORY=512Mb</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MEILI_MAX_INDEXING_THREADS=2</span></span></code></pre></div><p>With these settings:</p><ul><li>Indexing memory stays capped at 512 MB.</li><li>Operating system page caches handle disk I/O smoothly.</li><li>Search queries remain responsive on the live <code>places</code> index during background shadow builds.</li></ul><hr><h2 id="benchmark-footprint-comparison" tabindex="-1">Benchmark &amp; Footprint Comparison <a class="header-anchor" href="#benchmark-footprint-comparison" aria-label="Permalink to &quot;Benchmark &amp; Footprint Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Traditional OSM Pipelines</th><th style="text-align:left;">Geomilli Harvester</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Go Process RSS (Belgium)</strong></td><td style="text-align:left;">~450 MB</td><td style="text-align:left;"><strong>&lt; 35 MB</strong></td></tr><tr><td style="text-align:left;"><strong>Go Process RSS (Planet)</strong></td><td style="text-align:left;">32 GB – 64 GB</td><td style="text-align:left;"><strong>&lt; 65 MB</strong></td></tr><tr><td style="text-align:left;"><strong>Intermediate Storage</strong></td><td style="text-align:left;">Cumulative (150+ GB)</td><td style="text-align:left;"><strong>Ephemeral (&lt; 5 GB peak)</strong></td></tr><tr><td style="text-align:left;"><strong>Indexing Downtime</strong></td><td style="text-align:left;">Minutes to Hours</td><td style="text-align:left;"><strong>0 ms (Atomic Swap)</strong></td></tr></tbody></table>`,25))])}const B=r(h,[["render",g]]);export{x as __pageData,B as default};
